 Call(f,"Attach");Call(f,"RefreshInspector");var share=(ShareService)Get(f,"sharing");var preferences=All(f).OfType<ToggleSwitch>().Where(c=>c.Visible).ToArray();var clipboard=preferences.First(c=>c.AccessibleName=="Clipboard sharing");bool clipBefore=share.ClipboardEnabled;typeof(Control).GetMethod("OnClick",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(clipboard,new object[]{EventArgs.Empty});Check(share.ClipboardEnabled!=clipBefore&&Wire.LoadSecret("clipboard-enabled.bin","")==(share.ClipboardEnabled?"true":"false"),"inline clipboard toggle applies and persists");var files=preferences.First(c=>c.AccessibleName=="File sharing");bool filesBefore=share.FilesEnabled;typeof(Control).GetMethod("OnClick",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(files,new object[]{EventArgs.Empty});Check(share.FilesEnabled!=filesBefore&&Wire.LoadSecret("files-enabled.bin","")==(share.FilesEnabled?"true":"false"),"inline file toggle applies and persists");
 Check(preferences.Length==3,"exactly three sharing switches");Check(!((Control)Get(f,"mediaMic")).Visible&&!((Control)Get(f,"mediaSpeaker")).Visible,"media off hides routing choices");
 Call(f,"SetMediaEnabled",true);Check(((Control)Get(f,"mediaMic")).Visible&&((Control)Get(f,"mediaSpeaker")).Visible,"media on reveals independent routing controls");Check(((Control)Get(f,"localMic")).Enabled&&((Control)Get(f,"localSpeaker")).Enabled,"local hardware selectors enabled for this PC sources");f.ClientSize=new Size(1440,820);Application.DoEvents();var speakerControl=(Control)Get(f,"localSpeaker");var quitControl=All(f).First(c=>c.Name=="QuitApp");Check(speakerControl.PointToScreen(new Point(0,speakerControl.Height)).Y<=quitControl.PointToScreen(Point.Empty).Y,"hardware speaker remains visible above pinned Quit at 1440x820");using(var bmp=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bmp,new Rectangle(0,0,bmp.Width,bmp.Height));bmp.Save("build/qa-media-enabled.png");}Call(f,"SetMediaEnabled",false);Check(!((MicrophoneShare)Get(f,"microphone")).AllowRemoteRequests&&!((MicrophoneShare)Get(f,"microphone")).ReceiveEnabled,"media off revokes microphone send and receive access");
