 var collapsed=session.Devices[1];collapsed.online=false;using(var bmp=new Bitmap(canvas.Width,canvas.Height)){canvas.DrawToBitmap(bmp,canvas.ClientRectangle);var bounds=canvas.Card(collapsed);Check(Math.Min(bounds.Width,bounds.Height)<=7,"offline device is a six-pixel placeholder");canvas.Zoom(.8f);canvas.DrawToBitmap(bmp,canvas.ClientRectangle);var zoomed=canvas.Card(collapsed);Check(Math.Min(zoomed.Width,zoomed.Height)<=7,"offline strip stays thin when zoomed");canvas.Fit();canvas.DrawToBitmap(bmp,canvas.ClientRectangle);bmp.Save("build/qa-collapsed-device.png");}collapsed.online=true;
